import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class codeforces {

    static int[] scanWord(char[] ch, int n, int start) {
        int count = 0;
        int j = start;
        while (true) {
            if (ch[j] != '_' && ch[j] != '(') {
                count++;
            }
            if (ch[j] == '_' || ch[j] == '(' || j == n - 1) {
                return new int[]{j, count};
            }
            j++;
        }
    }

    static int scanInside(char[] ch, int n, int start, int[] counter) {
        int count = 0;
        int j = start;
        while (true) {
            if (j >= n) {
                return start;
            }
            if ((ch[j] == '_' || ch[j] == ')') && count > 0) {
                counter[0]++;
                count = 0;
            }
            if (ch[j] == ')') {
                return j;
            }
            if (ch[j] != '_' && ch[j] != '(') {
                count++;
            }
            j++;
        }
    }

    public static void main(String[] args) throws IOException {
        Reader.init(System.in);
        int n = Reader.nextInt();
        int max = 0;
        int countw = 0;
        String x = Reader.next();
        char[] ch = x.toCharArray();

        int i = 0;
        while (i < n) {
            if (ch[i] != '_' && ch[i] != '(') {
                int[] r = scanWord(ch, n, i);
                max = Math.max(max, r[1]);
                i = r[0];
            }
            if (ch[i] == '(') {
                int[] add = new int[1];
                i = scanInside(ch, n, i, add);
                countw += add[0];
            }
            i++;
        }

        System.out.println(max + " " + countw);
    }
}

class Reader {
    static BufferedReader reader;
    static StringTokenizer tokenizer;

    static void init(InputStream input) {
        reader = new BufferedReader(new InputStreamReader(input));
        tokenizer = new StringTokenizer("");
    }

    static String next() throws IOException {
        while (!tokenizer.hasMoreTokens()) {
            tokenizer = new StringTokenizer(reader.readLine());
        }
        return tokenizer.nextToken();
    }

    static int nextInt() throws IOException {
        return Integer.parseInt(next());
    }

    static double nextDouble() throws IOException {
        return Double.parseDouble(next());
    }
}
